import json

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_text = t[m.end():].split('\n')[:h]
        rows = [r.split() for r in rows_text if r.strip()]
        valid = all(len(r) == w and all(x.isdigit() for x in r) for r in rows)
        if valid and k not in G:
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()

def normalize_shape(cells):
    rows = set(c[0] for c in cells)
    cols = set(c[1] for c in cells)
    min_r, min_c = min(rows), min(cols)
    normalized = []
    for r, c in cells:
        normalized.append((r - min_r, c - min_c))
    return sorted(normalized)

def apply_shape_matching(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                comp = []
                stack = [(r,c)]
                val = grid[r][c]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == val and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                normalized = normalize_shape(comp)
                comps.append((val, tuple(normalized), sorted(comp)))

    result = [row[:] for row in grid]

    from collections import defaultdict
    shape_groups = defaultdict(list)
    for color, norm_shape, orig_cells in comps:
        shape_groups[norm_shape].append((color, orig_cells))

    for norm_shape, members in shape_groups.items():
        # Find max color in group
        max_color = max(color for color, cells in members)

        # Replace all non-max components with max_color
        for orig_color, orig_cells in members:
            if orig_color != max_color:
                for rr, cc in orig_cells:
                    result[rr][cc] = max_color

    return result

